function flushNotify(pi: ExtensionAPI, m: MonitorState): void {
	if (m.pendingLines.length === 0) return;
	const lines = m.pendingLines;
	m.pendingLines = [];
	if (m.flushTimer) {
		clearTimeout(m.flushTimer);
		m.flushTimer = undefined;
	}
	if (runtimeStale) return;
	const tail = lines.slice(-NOTIFY_TAIL_LINES);
	const suppressed = Math.max(0, lines.length - tail.length);
	const duplicateNote = m.suppressedDuplicateLines > 0 ? ` · ${m.suppressedDuplicateLines} duplicate line${m.suppressedDuplicateLines !== 1 ? "s" : ""} suppressed` : "";
	const body = tail.length > 0 ? `\n${tail.join("\n")}` : "";
	const suffix = suppressed > 0 ? `\n…(${suppressed} more lines saved to ${m.logPath})` : "";
	if (!m.triggerOnOutput) {
		// Claude/Codex-style backgrounding: output updates the UI/log, but does not
		// inject steering messages into the active agent loop. This prevents a log
		// tail or watcher from waking the model on every batch and causing the
		// "waited for background terminal" ping-pong Luke reported.
		safeNotify(activeCtx, `monitor ${m.description}: ${lines.length} new line${lines.length !== 1 ? "s" : ""} · ${m.logPath}`);
		return;
	}
	if (m.wakeCount >= m.maxWakeups) {
		m.triggerOnOutput = false;
		m.outputWakeDisabledReason = `maxWakeups ${m.maxWakeups} reached`;
		safeNotify(activeCtx, `monitor ${m.description}: output wakeups disabled after ${m.maxWakeups}; continuing to log to ${m.logPath}`, "warning");
		return;
	}
	m.wakeCount++;
	const wakeNote = `wake ${m.wakeCount}/${m.maxWakeups}`;
	safeSend(
		pi,
		{
			customType: "monitor-event",
			content: `[monitor ${m.description}] ${lines.length} new line${lines.length !== 1 ? "s" : ""} · ${wakeNote}${duplicateNote} · full log: ${m.logPath}${body}${suffix}`,
			display: true,
			details: { monitorId: m.id, tail, status: m.status, logPath: m.logPath, suppressed, totalLines: m.totalLines, wakeCount: m.wakeCount, maxWakeups: m.maxWakeups },
		},
		{ deliverAs: "steer", triggerTurn: true },
