/**
 * native-tool-overrides
 *
 * Registers Luke's native tools by wrapping Pi's lowercase tool factories and overriding
 * their behavior — Edit argument repair, Bash timeout-to-background, deferred loading,
 * and Claude-style UI labels ("Read"/"Bash"/...) via ToolDefinition.label while keeping
 * upstream lowercase wire names (read/edit/write/grep/find/ls/bash). Also owns the
 * web_fetch/web_search marker tools (claude-bridge native server tools that throw on
 * local execute). This is more than aliasing: it is the override layer that keeps
 * custom tool behavior out of pi-mono-fork core.
 *
 * Lifts these tool definitions out of pi-mono-fork core so the fork can stay closer
 * to upstream Pi. The hardcoded tool-name references in `agent-session.ts` and `sdk.ts`
 * (defaultActiveToolNames, CLAUDE_BRIDGE_NATIVE_TOOL_NAMES) resolve to these
 * extension-provided tools at session startup via the runtime tool registry.
 *
 * Naming: lowercase wire names match core factories (so the extension tool overwrites
 * the core builtin by registry key and the bridge presents CC-canonical casing); UI
 * display comes from `label`. High-traffic edit/shell/read tools are always loaded;
 * utility tools stay provider-native deferred so they are available without billing
 * their full schemas every turn. Agent stays capitalized (core filters an extension
 * tool named "agent" when the core "agent" builtin exists).
 */

import {
  AGENTS_ENGINE_SERVICE_ID,
  BASH_BG_JOBS_SERVICE_ID,
  type AgentEngine,
  type BashBgJobStore,
  createBashBgJobStore,
  createBashToolDefinition,
  createEditToolDefinition,
  createFindToolDefinition,
  createGrepToolDefinition,
  createLsToolDefinition,
  createReadToolDefinition,
  createTaskListToolDefinition,
  createTaskOutputToolDefinition,
  createTaskStopToolDefinition,
  createUppercaseAgentToolDefinition,
  createWriteToolDefinition,
  type ExtensionAPI,
  onBashTimeout,
} from "@valkyriweb/pi-coding-agent";
import { Container, Text } from "@valkyriweb/pi-tui";
import { type Static, Type } from "typebox";
import { readFileSync } from "node:fs";
import { homedir } from "node:os";
import { join, resolve } from "node:path";

// --- Per-profile tool selection (include / exclude) ----------------------------
//
// Lets a profile register only a subset of the canonical native tools without
// forking this extension. Resolution order (first wins per field):
//   1. env: PI_NATIVE_TOOL_INCLUDE / PI_NATIVE_TOOL_EXCLUDE (comma-separated)
//   2. settings.json: extensions.native-tool-overrides.{include,exclude}
//   3. defaults (register everything)
//
// `include` is an allowlist (only these register). `exclude` is a denylist
// (everything except these). If both resolve, include is applied first, then
// exclude removes from it. Names match the capability case-insensitively
// (e.g. "Agent", "agent" both exclude the Agent alias).
//
// CACHE CRITICAL: this is read once at load and gates which schemas enter the
// stable first-turn tools[] set. It must be deterministic per process; never
// derive it from per-turn state.
interface NativeToolSelection {
  include: Set<string> | null;
  exclude: Set<string>;
}

function parseNameList(raw: unknown): string[] {
  if (typeof raw === "string") return raw.split(",").map((s) => s.trim()).filter(Boolean);
  if (Array.isArray(raw)) return raw.filter((s): s is string => typeof s === "string").map((s) => s.trim()).filter(Boolean);
  return [];
}

function loadSelection(): NativeToolSelection {
  let includeNames = parseNameList(process.env.PI_NATIVE_TOOL_INCLUDE);
  let excludeNames = parseNameList(process.env.PI_NATIVE_TOOL_EXCLUDE);

  if (includeNames.length === 0 || excludeNames.length === 0) {
    const path = join(process.env.PI_CODING_AGENT_DIR || join(homedir(), ".pi", "agent"), "settings.json");
    try {
      const raw = readFileSync(path, "utf8");
      const parsed = JSON.parse(raw) as {
        extensions?: { "native-tool-overrides"?: { include?: unknown; exclude?: unknown } };
      };
      const cfg = parsed.extensions?.["native-tool-overrides"];
      if (includeNames.length === 0) includeNames = parseNameList(cfg?.include);

