31	export function formatCwdForFooter(cwd: string, home: string | undefined): string {
32		if (!home) return cwd;
33	
34		const resolvedCwd = resolve(cwd);
35		const resolvedHome = resolve(home);
36		const relativeToHome = relative(resolvedHome, resolvedCwd);
37		const isInsideHome =
38			relativeToHome === "" ||
39			(relativeToHome !== ".." && !relativeToHome.startsWith(`..${sep}`) && !isAbsolute(relativeToHome));
