65	 * Computes token/context stats from session, gets git branch and extension statuses from provider.
66	 */
67	export class FooterComponent implements Component {
68		private autoCompactEnabled = true;
69		private session: AgentSession;
70		private footerData: ReadonlyFooterDataProvider;
71		private usageCacheKey = "";
72		private usageCache: UsageTotals = {
73			totalInput: 0,
74			totalOutput: 0,
75			totalCacheRead: 0,
76			totalCacheWrite: 0,
77			totalCost: 0,
78			assistantTurns: 0,
79		};
80		private selectedExtensionFooterId: string | undefined = undefined;
81	
82		constructor(session: AgentSession, footerData: ReadonlyFooterDataProvider) {
83			this.session = session;
84			this.footerData = footerData;
85		}
86	
87		setSelectedExtensionFooterId(id: string | undefined): void {
88			this.selectedExtensionFooterId = id;
89		}
90	
91		setSession(session: AgentSession): void {
92			this.session = session;
93		}
94	
95		setAutoCompactEnabled(enabled: boolean): void {
96			this.autoCompactEnabled = enabled;
97		}
98	
99		/**
100		 * No-op: git branch caching now handled by provider.
101		 * Kept for compatibility with existing call sites in interactive-mode.
102		 */
103		invalidate(): void {
104			// No-op: git branch is cached/invalidated by provider
105		}
106	
107		/**
108		 * Clean up resources.
109		 * Git watcher cleanup now handled by provider.
110		 */
111		dispose(): void {
112			// Git watcher cleanup handled by provider
113		}
