115		/** Render extension-contributed footer pills at the bottom of the footer. */
116		private renderBackgroundStatusLine(width: number): string | undefined {
117			const parts = this.session.extensionRunner
118				.getRegisteredFooters()
119				.filter(({ spec }) => spec.visible?.() ?? true)
120				.sort((a, b) => (a.spec.order ?? 0) - (b.spec.order ?? 0))
121				.map(({ id, spec }) =>
122					sanitizeStatusText(
123						spec.render({
124							width,
125							theme,
126							selected: id === this.selectedExtensionFooterId,
127						}),
128					),
