import assert from "node:assert/strict";
import { createJiti } from "jiti";
import { createBashToolDefinition } from "@valkyriweb/pi-coding-agent";

// Regression: the Bash detach-on-timeout policy must survive session dispose.
//
// `native-tool-overrides` installs a process-global detach resolver via
// `onBashTimeout`. It used to call the returned restore fn from its
// `onSessionDispose` handler, which reverted the resolver to core's kill policy.
// Because the resolver is a single package-global (not a per-session value), any
// top-level dispose (/new, /fork, switchSession) left a window where a timed-out
// command was KILLED instead of auto-backgrounded. This test drives the real
// extension factory + real package through the activate/dispose lifecycle with a
// genuine 1s-timeout `sleep` and asserts the policy stays "detach".

const ctx = {};
const text = (r) => r?.content?.[0]?.text ?? "";

// Probe the current global resolver by running a command that exceeds its timeout.
// Returns "detach" when the live process is adopted into a bg job, else "kill".
async function probe() {
  const bash = createBashToolDefinition(process.cwd());
  try {
    const r = await bash.execute("p", { command: "sleep 3", timeout: 1 }, undefined, undefined, ctx);
    return /detached into background job/.test(text(r)) ? "detach" : `unexpected:${text(r).slice(0, 60)}`;
  } catch (e) {
    return /timed out after/.test(String(e?.message)) ? "kill" : `error:${e?.message}`;
  }
}

const jiti = createJiti(import.meta.url, { interopDefault: true, fsCache: false });
const mod = await jiti.import("./index.ts");
const factory = mod.default ?? mod;

function activate() {
  const services = new Map();
  let disposeHandler = () => {};
  factory({
    on: () => {},
    registerTool: () => {},
    registerCommand: () => {},
    registerShortcut: () => {},
    registerFlag: () => {},
    onSessionDispose: (h) => { disposeHandler = h; },
    hooks: { removeAction: () => {} },
    harness: {
      provide: (id, service) => { services.set(id, service); return { id, current: () => service, replace: (n) => services.set(id, n), dispose: () => services.delete(id) }; },
      use: (id) => services.get(id),
    },
  });
  return disposeHandler;
}

assert.equal(await probe(), "kill", "baseline: core default kills a timed-out command");

const disposeA = activate();
assert.equal(await probe(), "detach", "after activation: timed-out command auto-backgrounds");

disposeA();
assert.equal(await probe(), "detach", "after session dispose (no re-activation): policy must persist");

const disposeB = activate();
disposeB();
disposeA();
assert.equal(await probe(), "detach", "after stacked disposes: policy must not be clobbered to kill");

console.log("pi-native-tool-overrides auto-background lifecycle test passed");

