import {
  createBashToolDefinition,
} from "@valkyriweb/pi-coding-agent";

const ctx = {};
const text = (r) => r?.content?.[0]?.text ?? "";

// Probe the CURRENT global resolver state by running a real timing-out command.
// detach => resolver is the detach policy; kill => core default (kill+timeout).
async function probe(label) {
  const bash = createBashToolDefinition(process.cwd());
  try {
    const r = await bash.execute("p", { command: "sleep 3", timeout: 1 }, undefined, undefined, ctx);
    const t = text(r);
    const detached = /detached into background job/.test(t);
    console.log(`${label}: ${detached ? "DETACH ✅" : "??? " + t.slice(0, 80)}`);
  } catch (e) {
    console.log(`${label}: KILL ❌ (${String(e.message).split("\n").pop()})`);
  }
}

// Load the real extension factory against a stub api; capture its dispose handler.
function loadExtensionFactory() {
  const jiti = createJiti(import.meta.url, { interopDefault: true, fsCache: false });
  return jiti.import(process.env.NTO_INDEX);
}

async function activate(factory) {
  const services = new Map();
  let disposeHandler = () => {};
  const stubApi = {
    on: () => {},
    registerTool: () => {},
    registerCommand: () => {},
    registerShortcut: () => {},
    registerFlag: () => {},
    onSessionDispose: (h) => { disposeHandler = h; },
    hooks: { removeAction: () => {} },
    harness: {
      provide: (id, service) => { services.set(id, service); return { id, current: () => service, replace: (n) => services.set(id, n), dispose: () => services.delete(id) }; },
      use: (id) => services.get(id),
    },
  };
  factory(stubApi);
  return disposeHandler;
}

const mod = await loadExtensionFactory();
const factory = mod.default ?? mod;

console.log("\n--- Auto-background resolver lifecycle repro ---\n");
await probe("0. baseline (no extension)            ");
const dispose1 = await activate(factory);
await probe("1. after activate (session A start)   ");
dispose1();
await probe("2. after dispose A (NO new session)   ");
const dispose2 = await activate(factory);
await probe("3. after activate (session B start)   ");
dispose2();
dispose1();
await probe("4. after double-dispose (stacked)     ");
process.exit(0);

