141		private getUsageTotals(): UsageTotals {
142			const entries = this.getUsageEntries();
143			let lastUsage: UsageSnapshot | undefined;
144			for (let i = entries.length - 1; i >= 0; i--) {
145				const entry = entries[i];
146				if (entry?.type === "message" && entry.message.role === "assistant") {
147					lastUsage = entry.message.usage;
148					break;
149				}
150			}
151			const latestCompaction = getLatestCompactionEntry(entries);
152			const cacheKey = [
153				entries.length,
154				entries.at(-1)?.id ?? "",
155				latestCompaction?.id ?? "",
156				latestCompaction?.timestamp ?? "",
157				lastUsage?.input ?? 0,
158				lastUsage?.output ?? 0,
159				lastUsage?.cacheRead ?? 0,
160				lastUsage?.cacheWrite ?? 0,
161				lastUsage?.cost.total ?? 0,
162			].join(":");
163	
164			if (cacheKey === this.usageCacheKey) {
165				return this.usageCache;
166			}
167	
168			const totals: UsageTotals = {
169				totalInput: 0,
170				totalOutput: 0,
171				totalCacheRead: 0,
172				totalCacheWrite: 0,
173				totalCost: 0,
174				assistantTurns: 0,
175				lastUsage,
176			};
177	
178			const startIndex =
179				latestCompaction === null ? 0 : entries.findIndex((entry) => entry.id === latestCompaction.id) + 1;
180			for (const entry of entries.slice(startIndex)) {
181				if (entry.type === "message" && entry.message.role === "assistant") {
182					totals.totalInput += entry.message.usage.input;
183					totals.totalOutput += entry.message.usage.output;
184					totals.totalCacheRead += entry.message.usage.cacheRead;
185					totals.totalCacheWrite += entry.message.usage.cacheWrite;
186					totals.totalCost += entry.message.usage.cost.total;
187					totals.assistantTurns += 1;
188				}
189			}
190	
191			this.usageCacheKey = cacheKey;
192			this.usageCache = totals;
193			return totals;
194		}
195	
196		render(width: number): string[] {
197			const state = this.session.state;
198			const { totalInput, totalOutput, totalCacheRead, totalCacheWrite, totalCost, assistantTurns, lastUsage } =
199				this.getUsageTotals();
200	
201			const contextUsage = this.session.getContextUsage();
202			const contextWindow = contextUsage?.contextWindow ?? state.model?.contextWindow ?? 0;
203			const contextPercentValue = contextUsage?.percent ?? 0;
204			const contextPercent = contextUsage?.percent !== null ? contextPercentValue.toFixed(1) : "?";
205			const contextTokens = contextUsage?.tokens ?? null;
206			const knownTokens = contextTokens ?? 0;
207	
208			// CWD with ~ substitution
209			const basePwd = formatCwdForFooter(
210				this.session.sessionManager.getCwd(),
211				process.env.HOME || process.env.USERPROFILE,
212			);
213	
214			const branch = this.footerData.getGitBranch();
215			const sessionName = this.session.sessionManager.getSessionName();
216	
217			// Dim middle-dot separator
218			const sep = theme.fg("dim", " · ");
219	
220			// ── Line 1: pwd · branch · session ────────────────────────────────────────
221			let pwdContent = theme.fg("muted", basePwd);
222			if (branch) {
223				pwdContent += theme.fg("dim", " (") + theme.fg("borderAccent", theme.bold(branch)) + theme.fg("dim", ")");
224			}
225			if (sessionName) {
226				pwdContent += sep + theme.fg("accent", sessionName);
227			}
228			const pwdLine = truncateToWidth(pwdContent, width, theme.fg("dim", "..."));
229	
230			// ── Line 2: token stats · context% ··············· model · thinking ───────
231			const leftParts: string[] = [];
232			if (totalInput) leftParts.push(theme.fg("dim", `↑${formatTokens(totalInput)}`));
233			if (totalOutput) leftParts.push(theme.fg("dim", `↓${formatTokens(totalOutput)}`));
234			if (totalCacheRead) leftParts.push(theme.fg("dim", `R${formatTokens(totalCacheRead)}`));
235			if (totalCacheWrite) leftParts.push(theme.fg("dim", `W${formatTokens(totalCacheWrite)}`));
236			// Provider usage is normalized into non-cached input, cache reads, and
237			// cache writes. Show cache warmth for the latest turn, not cumulative
238			// session totals: a two-turn Codex session has one cold turn + one warm turn,
239			// so cumulative math misleadingly displays 50% even when turn 2 is fully warm.
240			const latestCacheRead = lastUsage?.cacheRead ?? 0;
241			const latestCacheWrite = lastUsage?.cacheWrite ?? 0;
242			const latestInput = lastUsage?.input ?? 0;
243			const cacheDenom = latestInput + latestCacheRead + latestCacheWrite;
244			if (cacheDenom > 0) {
245				const hitPct = (latestCacheRead / cacheDenom) * 100;
246				const totalCacheDenom = totalInput + totalCacheRead + totalCacheWrite;
247				const avgPct = totalCacheDenom > 0 ? (totalCacheRead / totalCacheDenom) * 100 : undefined;
248				const label =
249					avgPct === undefined
250						? `cache ${hitPct.toFixed(0)}%`
251						: `cache ${hitPct.toFixed(0)}% avg ${avgPct.toFixed(0)}%`;
252				// Past the warmup window (≥10 assistant turns) the prefix should be
253				// steady-state cached. <90% means real drift; <80% means something is
254				// mutating the cached prefix every turn. Under 10 turns we keep the
255				// loose thresholds because turn 1 always writes the full prefix.
256				const steadyState = assistantTurns >= 10;
257				let colored: string;
258				if (steadyState) {
259					if (hitPct >= 90) colored = theme.fg("success", label);
260					else if (hitPct >= 80) colored = theme.fg("warning", label);
261					else colored = theme.fg("error", theme.bold(label));
262				} else {
263					if (hitPct >= 80) colored = theme.fg("success", label);
264					else if (hitPct >= 50) colored = theme.fg("dim", label);
265					else colored = theme.fg("warning", label);
266				}
267				leftParts.push(colored);
268			}
269	
270			const usingSubscription = state.model ? this.session.modelRegistry.isUsingOAuth(state.model) : false;
271			if (totalCost || usingSubscription) {
272				const costStr = `$${totalCost.toFixed(3)}${usingSubscription ? " (sub)" : ""}`;
273				leftParts.push(theme.fg("dim", costStr));
274			}
275			if (assistantTurns) leftParts.push(theme.fg("dim", `t${assistantTurns}`));
276	
277			// Context % — each piece coloured independently (no outer dim wrapper)
278			const autoIndicator = this.autoCompactEnabled ? " (auto)" : "";
279			const contextTokensDisplay = contextTokens === null ? "?" : formatTokens(contextTokens);
280			const percentLabel = contextPercent === "?" ? "?%" : `${contextPercent}%`;
281			const tokensLabel = `${contextTokensDisplay}/${formatTokens(contextWindow)}${autoIndicator}`;
282	
283			let ctxPct: string;
284			if (contextPercentValue > 90) {
285				ctxPct = theme.fg("error", theme.bold(percentLabel));
286			} else if (contextPercentValue > 70) {
287				ctxPct = theme.fg("warning", theme.bold(percentLabel));
288			} else if (knownTokens < 25_000) {
289				ctxPct = theme.fg("success", theme.bold(percentLabel));
290			} else {
291				ctxPct = theme.fg("success", percentLabel);
292			}
293			leftParts.push(`${ctxPct} ${theme.fg("dim", tokensLabel)}`);
294	
295			const statsLeft = leftParts.join(sep);
296			let statsLeftWidth = visibleWidth(statsLeft);
297			if (statsLeftWidth > width) statsLeftWidth = visibleWidth(truncateToWidth(statsLeft, width, "..."));
298	
299			// Right side: model (warm yellow) · thinking level (teal)
300			const modelName = state.model?.id || "no-model";
301			const rightParts: string[] = [theme.fg("syntaxFunction", modelName)];
302			if (state.model?.reasoning) {
303				const thinkingLevel = state.thinkingLevel || "off";
304				rightParts.push(thinkingLevel === "off" ? theme.fg("dim", "thinking off") : theme.fg("accent", thinkingLevel));
305			}
306			let rightSide = rightParts.join(sep);
307	
308			// Prepend provider if multiple providers and there's room
309			const minPadding = 2;
310			if (this.footerData.getAvailableProviderCount() > 1 && state.model) {
311				const withProvider = theme.fg("dim", `(${state.model.provider}) `) + rightSide;
312				if (statsLeftWidth + minPadding + visibleWidth(withProvider) <= width) {
313					rightSide = withProvider;
314				}
315			}
316	
317			const rightSideWidth = visibleWidth(rightSide);
318			let statsLine: string;
319			if (statsLeftWidth + minPadding + rightSideWidth <= width) {
320				const padding = " ".repeat(width - statsLeftWidth - rightSideWidth);
321				statsLine = statsLeft + padding + rightSide;
322			} else {
323				const availableForRight = width - statsLeftWidth - minPadding;
324				if (availableForRight > 0) {
325					const truncatedRight = truncateToWidth(rightSide, availableForRight, "");
326					const truncatedRightWidth = visibleWidth(truncatedRight);
327					const padding = " ".repeat(Math.max(0, width - statsLeftWidth - truncatedRightWidth));
328					statsLine = statsLeft + padding + truncatedRight;
329				} else {
330					statsLine = truncateToWidth(statsLeft, width, theme.fg("dim", "..."));
331				}
332			}
333	
334			const lines = [pwdLine, statsLine];
335	
336			const backgroundStatusLine = this.renderBackgroundStatusLine(width);
337			if (backgroundStatusLine) {
338				lines.push(backgroundStatusLine);
339			}
340	
341			// Add extension statuses on a single line, sorted by key alphabetically
342			const extensionStatuses = this.footerData.getExtensionStatuses();
343			if (extensionStatuses.size > 0) {
344				const sortedStatuses = Array.from(extensionStatuses.entries())
345					.sort(([a], [b]) => a.localeCompare(b))
346					.map(([, text]) => sanitizeStatusText(text));
347				const statusLine = sortedStatuses.join(" ");
348				// Truncate to terminal width with dim ellipsis for consistency with footer style
349				lines.push(truncateToWidth(statusLine, width, theme.fg("dim", "...")));
350			}
351	
352			return lines;
353		}
354	}
